const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

// Only process PCS_FAULT_GRP_1 (0x66B978x)
if ((canId & 0xFFFFFFF0) !== 0x66B9780) {
    return null;
}

// Helper function to get bit value
function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

let state = {
    kind: "PcsFaultGrp1State",
    version: 1,
    timestampUtc: new Date().toISOString(),

    // ==================== Byte 0 (Bit 0-7) ====================
    pcs_hwEpoFault: getBit(data, 0),             // Bit 0 - HW EPO Fault
    pcs_hwIgbtOcpFault: getBit(data, 1),         // Bit 1 - HW IGBT OCP Fault
    pcs_hwBusOvFault: getBit(data, 2),           // Bit 2 - HW Bus Over Voltage Fault
    pcs_hwWaveLimitFault: getBit(data, 3),       // Bit 3 - HW Wave Limit Fault
    pcs_hwBalWaveLimitFault: getBit(data, 4),    // Bit 4 - HW Balance Wave Limit Fault
    pcs_hw24vPwrFault: getBit(data, 5),          // Bit 5 - HW 24V Power Fault
    pcs_hwFanFault: getBit(data, 6),             // Bit 6 - HW Fan Fault
    pcs_hwConnFault: getBit(data, 7),            // Bit 7 - HW Connection Fault

    // ==================== Byte 1 (Bit 8-15) ====================
    pcs_hwExtDi3Fault: getBit(data, 8),          // Bit 8 - HW External DI3 Fault
    pcs_hwIndOvertFault: getBit(data, 9),        // Bit 9 - HW Inductance Over Temperature Fault
    pcs_hwPwrModOvert: getBit(data, 10),         // Bit 10 - HW Power Module Over Temperature
    pcs_hwBalOvert: getBit(data, 11),            // Bit 11 - HW Balance Over Temperature
    pcs_hw15vPwrFault: getBit(data, 12),         // Bit 12 - HW 15V Power Fault
    pcs_hwFireAlarmFault: getBit(data, 13),      // Bit 13 - HW Fire Alarm Fault
    pcs_hwExtDi1Fault: getBit(data, 14),         // Bit 14 - HW External DI1 Fault
    pcs_hwExtDi2Fault: getBit(data, 15),         // Bit 15 - HW External DI2 Fault

    // ==================== Byte 2 (Bit 16-23) ====================
    pcs_gridAOvFault: getBit(data, 16),          // Bit 16 - Grid A Over Voltage Fault
    pcs_gridBOvFault: getBit(data, 17),          // Bit 17 - Grid B Over Voltage Fault
    pcs_gridCOvFault: getBit(data, 18),          // Bit 18 - Grid C Over Voltage Fault
    pcs_gridAUvFault: getBit(data, 19),          // Bit 19 - Grid A Under Voltage Fault
    pcs_gridBUvFault: getBit(data, 20),          // Bit 20 - Grid B Under Voltage Fault
    pcs_gridCUvFault: getBit(data, 21),          // Bit 21 - Grid C Under Voltage Fault
    pcs_gridOverfFault: getBit(data, 22),        // Bit 22 - Grid Over Frequency Fault
    pcs_gridUnderfFault: getBit(data, 23),       // Bit 23 - Grid Under Frequency Fault

    // ==================== Byte 3 (Bit 24-31) ====================
    pcs_gridPhSeqFault: getBit(data, 24),        // Bit 24 - Grid Phase Sequence Fault
    pcs_gridAOcFault: getBit(data, 25),          // Bit 25 - Grid A Over Current Fault
    pcs_gridBOcFault: getBit(data, 26),          // Bit 26 - Grid B Over Current Fault
    pcs_gridCOcFault: getBit(data, 27),          // Bit 27 - Grid C Over Current Fault
    pcs_gridVUnbalFault: getBit(data, 28),       // Bit 28 - Grid Voltage Unbalance Fault
    pcs_gridIUnbalFault: getBit(data, 29),       // Bit 29 - Grid Current Unbalance Fault
    pcs_gridPhLossFault: getBit(data, 30),       // Bit 30 - Grid Phase Loss Fault
    pcs_gridNOcFault: getBit(data, 31),          // Bit 31 - Grid N Over Current Fault

    // ==================== Byte 4 (Bit 32-39) ====================
    pcs_busPreOvFault: getBit(data, 32),         // Bit 32 - Bus Pre Over Voltage Fault
    pcs_busPreUvFault: getBit(data, 33),         // Bit 33 - Bus Pre Under Voltage Fault
    pcs_busRunOvFault: getBit(data, 34),         // Bit 34 - Bus Run Over Voltage Fault
    pcs_busRunUvFault: getBit(data, 35),         // Bit 35 - Bus Run Under Voltage Fault
    pcs_busUnbalFault: getBit(data, 36),         // Bit 36 - Bus Unbalance Fault
    pcs_batUvFault: getBit(data, 37),            // Bit 37 - Battery Under Voltage Fault
    pcs_batOvFault: getBit(data, 38),            // Bit 38 - Battery Over Voltage Fault
    pcs_dcPreOcFault: getBit(data, 39),          // Bit 39 - DC Pre Over Current Fault

    // ==================== Byte 5 (Bit 40-47) ====================
    pcs_dcOcFault: getBit(data, 40),             // Bit 40 - DC Over Current Fault
    pcs_balSwOcFault: getBit(data, 41),          // Bit 41 - Balance Switch Over Current Fault
    pcs_batRevFault: getBit(data, 42),           // Bit 42 - Battery Reverse Fault
    pcs_acPreToFault: getBit(data, 43),          // Bit 43 - AC Pre Timeout Fault
    pcs_acPreAOcFault: getBit(data, 44),         // Bit 44 - AC Pre A Over Current Fault
    pcs_acPreBOcFault: getBit(data, 45),         // Bit 45 - AC Pre B Over Current Fault
    pcs_acPreCOcFault: getBit(data, 46),         // Bit 46 - AC Pre C Over Current Fault
    pcs_acLeakOcFault: getBit(data, 47),         // Bit 47 - AC Leak Over Current Fault

    // ==================== Byte 6 (Bit 48-55) ====================
    pcs_acDcCompFault: getBit(data, 48),         // Bit 48 - AC DC Component Fault
    pcs_acPwrMisFault: getBit(data, 49),         // Bit 49 - AC Power Mismatch Fault
    pcs_sysRamFault: getBit(data, 50),           // Bit 50 - System RAM Fault
    pcs_sysEepromFault: getBit(data, 51),        // Bit 51 - System EEPROM Fault
    pcs_sysAdDriftFault: getBit(data, 52),       // Bit 52 - System AD Drift Fault
    pcs_sysBackComFault: getBit(data, 53),       // Bit 53 - System Back Communication Fault
    pcs_sysCanProtFault: getBit(data, 54),       // Bit 54 - System CAN Protocol Fault
    pcs_sysCpldComFault: getBit(data, 55),       // Bit 55 - System CPLD Communication Fault

    // ==================== Byte 7 (Bit 56-63) ====================
    pcs_sysDatalogFault: getBit(data, 56),       // Bit 56 - System Datalog Fault
    pcs_sysInsulFault: getBit(data, 57),         // Bit 57 - System Insulation Fault
    pcs_sysFwMisFault: getBit(data, 58),         // Bit 58 - System Firmware Mismatch Fault
    pcs_sysBmsStatFault: getBit(data, 59),       // Bit 59 - System BMS Status Fault
    pcs_sysStsComFault: getBit(data, 60),        // Bit 60 - System STS Communication Fault
    pcs_sysBmsComFault: getBit(data, 61),        // Bit 61 - System BMS Communication Fault
    pcs_sysParCanFault: getBit(data, 62),        // Bit 62 - System Parallel CAN Fault
    pcs_sysEmsComFault: getBit(data, 63)         // Bit 63 - System EMS Communication Fault
};

// ==================== Derived Fields ====================
const allFaultFlags = [
    'pcs_hwEpoFault', 'pcs_hwIgbtOcpFault', 'pcs_hwBusOvFault', 'pcs_hwWaveLimitFault',
    'pcs_hwBalWaveLimitFault', 'pcs_hw24vPwrFault', 'pcs_hwFanFault', 'pcs_hwConnFault',
    'pcs_hwExtDi3Fault', 'pcs_hwIndOvertFault', 'pcs_hwPwrModOvert', 'pcs_hwBalOvert',
    'pcs_hw15vPwrFault', 'pcs_hwFireAlarmFault', 'pcs_hwExtDi1Fault', 'pcs_hwExtDi2Fault',
    'pcs_gridAOvFault', 'pcs_gridBOvFault', 'pcs_gridCOvFault', 'pcs_gridAUvFault',
    'pcs_gridBUvFault', 'pcs_gridCUvFault', 'pcs_gridOverfFault', 'pcs_gridUnderfFault',
    'pcs_gridPhSeqFault', 'pcs_gridAOcFault', 'pcs_gridBOcFault', 'pcs_gridCOcFault',
    'pcs_gridVUnbalFault', 'pcs_gridIUnbalFault', 'pcs_gridPhLossFault', 'pcs_gridNOcFault',
    'pcs_busPreOvFault', 'pcs_busPreUvFault', 'pcs_busRunOvFault', 'pcs_busRunUvFault',
    'pcs_busUnbalFault', 'pcs_batUvFault', 'pcs_batOvFault', 'pcs_dcPreOcFault',
    'pcs_dcOcFault', 'pcs_balSwOcFault', 'pcs_batRevFault', 'pcs_acPreToFault',
    'pcs_acPreAOcFault', 'pcs_acPreBOcFault', 'pcs_acPreCOcFault', 'pcs_acLeakOcFault',
    'pcs_acDcCompFault', 'pcs_acPwrMisFault', 'pcs_sysRamFault', 'pcs_sysEepromFault',
    'pcs_sysAdDriftFault', 'pcs_sysBackComFault', 'pcs_sysCanProtFault', 'pcs_sysCpldComFault',
    'pcs_sysDatalogFault', 'pcs_sysInsulFault', 'pcs_sysFwMisFault', 'pcs_sysBmsStatFault',
    'pcs_sysStsComFault', 'pcs_sysBmsComFault', 'pcs_sysParCanFault', 'pcs_sysEmsComFault'
];

let activeFaults = [];
allFaultFlags.forEach(flag => {
    if (state[flag] === true) activeFaults.push(flag);
});

state.pcs_hasFaultGrp1 = activeFaults.length > 0;
state.pcs_activeFaultsGrp1 = activeFaults;
state.pcs_activeFaultCountGrp1 = activeFaults.length;

flow.set("pcsFaultGrp1State", state);
msg.payload = state;
return msg;

var state = flow.get("pcsFaultGrp1State");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
